import{_ as a,o as e,c as i,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const b=JSON.parse('{"title":"Git 与 GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/Git与GitHub.md","filePath":"必学工具/Git与GitHub.md","lastUpdated":1792430298000}'),l={name:"必学工具/Git与GitHub.md"};function o(d,t,n,s,h,u){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="git-与-github" tabindex="-1">Git 与 GitHub <a class="header-anchor" href="#git-与-github" aria-label="Permalink to &quot;Git 与 GitHub&quot;">​</a></h1><blockquote><p>程序员世界的「保存」与「协作」。本指南本身就是托管在 GitHub 上的开源项目，参与贡献的第一步就是学会 Git。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>所有课程作业、项目、论文代码都值得用 Git 管理（再也不用「最终版 v12」）；</li><li>开源安全项目（Kali 工具、漏洞库、CTF 题解）几乎都在 GitHub 上，这是你学习与展示的主阵地；</li><li>向本仓库提交 Issue / PR 也需要它。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><strong>仓库（Repository）</strong>：项目容器</li><li><strong>提交（Commit）</strong>：一次版本快照</li><li><strong>分支（Branch）</strong>：并行开发线（如 <code>main</code>）</li><li><strong>推送 / 拉取（Push / Pull）</strong>：本地与远程同步</li><li><strong>合并（Merge）与拉取请求（PR）</strong>：协作合并代码</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://git-scm.com/book/zh/v2" target="_blank" rel="noreferrer">Pro Git（官方中文版）</a></td><td>书</td><td>Git 权威教材，免费在线阅读</td></tr><tr><td><a href="https://learngitbranching.js.org/" target="_blank" rel="noreferrer">Learn Git Branching</a></td><td>交互</td><td>可视化学习分支，强烈推荐</td></tr><tr><td>GitHub 官方文档</td><td>文档</td><td>含 PR、Issues、Pages 等完整说明</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>本周内就把第一个仓库建起来（哪怕是笔记），日常提交；</li><li>学会看 <code>git log</code> 和 <code>git diff</code>，这是排查问题的基础；</li><li>用 GitHub Pages 部署你的第一个个人主页，顺便理解 <a href="./../贡献指南.html">本站的部署方式</a>。</li></ul>',10)])])}const g=a(l,[["render",o]]);export{b as __pageData,g as default};
